function enumerate_types(g):
    types <- []
    for v0 in 0..2g:
      for vp in 0..2g:
        for e in 0..3g:
          for w in 0..g:
            v <- v0 + vp
            if g + v = e + 1 + w           # genus formula
               and 3v <= 2w + 2e           # stability
               and v <= e + 1              # connectedness
               and vp <= w:                # weight positivity
              append (v0, vp, e, w) to types
    return types
